<script setup lang="ts">
import {ref,onMounted,onUnmounted,watch,computed} from 'vue';
import {formatBytes} from './format-bytes';
const props=defineProps<{run:string;disabled?:boolean}>();
const labels:Record<string,string>={added:'新增',deleted:'删除',replaced:'身份替换',moved:'移动',renamed:'重命名',moved_and_renamed:'移动并重命名',modified:'元数据 / 内容变化',absence_observed:'观察到缺失（运行未完成）',multiple_observations:'多次变化，需查看原始证据'};
type Item={fs_id:string;path:string;name:string;directory:boolean;size:string};
type Row={fs_id:string;action:string;old:Item|null;new:Item|null;source_change_sequences:string[];recorded_at_utc:string;cloud_observed_at_utc:string};
const loading=ref(false),error=ref(''),rows=ref<Row[]|null>(null),status=ref(''),filter=ref(''),page=ref(0),opened=ref(false),rawCount=ref(0);
const matched=computed(()=>(rows.value||[]).filter(row=>!filter.value||row.action===filter.value)),visible=computed(()=>matched.value.slice(page.value*100,(page.value+1)*100));
let active=true,revision=0,controller:AbortController|undefined;
async function load(){if(!active||props.disabled||loading.value)return;const request=++revision,run=props.run;controller?.abort();controller=new AbortController();loading.value=true;opened.value=true;try{const response=await fetch('/api/cloud-inventory/refresh/sync-log?run_id='+encodeURIComponent(run),{credentials:'same-origin',signal:controller.signal});if(!active||props.disabled||request!==revision)return;if(response.status===401){location.assign('/login?next=%2Fcloud%2Fcache');return}if(!response.ok)throw Error('同步变更读取失败；原始逐目录事件仍可在扫描历史中查看。');const value=await response.json();if(!active||props.disabled||request!==revision)return;if(value.run_id!==run||!Array.isArray(value.changes)||!value.changes.every((r:any)=>typeof r.fs_id==='string'&&/^[1-9][0-9]*$/.test(r.fs_id)&&Object.hasOwn(labels,r.action)&&Array.isArray(r.source_change_sequences)&&r.source_change_sequences.every((s:any)=>typeof s==='string'&&/^[1-9][0-9]*$/.test(s))))throw Error('同步变更身份或类型无效');rows.value=value.changes;status.value=value.status;rawCount.value=value.raw_count;error.value='';page.value=0}catch(e){if(active&&!props.disabled&&request===revision)error.value=e instanceof Error?e.message:String(e)}finally{if(request===revision)loading.value=false}}
watch(()=>props.run,()=>{revision++;controller?.abort();loading.value=false;rows.value=null;opened.value=false;filter.value='';page.value=0;error.value=''});
function stop(){revision++;controller?.abort();loading.value=false}
function hide(){active=false;stop()}
function show(){active=true}
watch(()=>props.disabled,value=>{if(value)stop()});
onMounted(()=>{window.addEventListener('pagehide',hide);window.addEventListener('pageshow',show)});
onUnmounted(()=>{hide();window.removeEventListener('pagehide',hide);window.removeEventListener('pageshow',show)});
</script>
<template><section class="cache-sync-log"><button class="button secondary compact" :disabled="disabled||loading" @click="load">{{loading?'正在读取…':opened?'重新读取本轮同步变更':'查看本轮同步变更（移动 / 改名 / 增删）'}}</button><p v-if="error" class="notice danger" role="alert">{{error}}</p><template v-if="rows"><p class="muted">按稳定文件 ID 关联的历史观察，共 {{rows.length}} 个项目、{{rawCount}} 条原始变化。运行状态：{{status}}。不改写原始记录，不将列表观察当作远端操作回执；未完成运行的缺失不标记为确定删除。</p><label>变化类型 <select v-model="filter" @change="page=0"><option value="">全部</option><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select></label><div class="event-table-scroll"><table><thead><tr><th>变化 / 文件 ID</th><th>原路径</th><th>新路径</th><th>大小</th><th>时间与原始证据</th></tr></thead><tbody><tr v-for="row in visible" :key="row.fs_id"><td>{{labels[row.action]}}<small>{{row.fs_id}}</small></td><td>{{row.old?.path||'—'}}</td><td>{{row.new?.path||'—'}}</td><td>{{row.new?.directory||row.old?.directory?'文件夹':formatBytes(row.new?.size??row.old?.size)}}</td><td><small>本机记录 {{row.recorded_at_utc}}</small><small>远端观察 {{row.cloud_observed_at_utc}}</small><small>原始变化序号 {{row.source_change_sequences.join('、')}}</small></td></tr><tr v-if="!visible.length"><td colspan="5">{{rows.length?'当前筛选没有项目。':'本轮没有可关联的差异记录；首次建档或缺少旧完整缓存时，可在原始事件查看覆盖情况。'}}</td></tr></tbody></table></div><div class="toolbar"><button class="button secondary compact" :disabled="page===0" @click="page--">上一页</button><span>筛选命中 {{matched.length}} 项</span><button class="button secondary compact" :disabled="(page+1)*100>=matched.length" @click="page++">下一页</button></div></template></section></template>
<style scoped>.cache-sync-log{margin:14px 0;padding:14px;border:1px solid #dae3ee;border-radius:8px}.cache-sync-log table{min-width:700px;width:100%;border-collapse:collapse}.cache-sync-log th,.cache-sync-log td{padding:9px;border-bottom:1px solid #e4eaf2;vertical-align:top;text-align:left;overflow-wrap:anywhere}.cache-sync-log small{display:block;font-size:11px;color:#65758a;margin:4px 0}.cache-sync-log .toolbar{display:flex;gap:10px;align-items:center;margin-top:10px}.cache-sync-log select{border:1px solid #ccd5e3;border-radius:6px;padding:6px;margin-bottom:10px}</style>
